entries[44222] = { ["name"] = "Dart Gun", ["text"] = "Quest Item\nUse: Fire a poisoned dart at an Orgrim's Hammer Scout. (40 yard range) (5 Sec Cooldown)" }
entries[44223] = { ["name"] = "Reins of the Black War Bear", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nRequires any Alliance race\nUse: Teaches you how to summon this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"Killing leaders of the Horde is its own reward, but this intimidating beast is an excellent memento.\"\nAchievement:\nFor The Alliance!\nCategory:\nPlayer vs. Player" }
entries[44224] = { ["name"] = "Reins of the Black War Bear", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nRequires any Horde race\nUse: Teaches you how to summon this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"This formidable mount is bought with the blood of Alliance leaders, but you would have killed them for free.\"\nAchievement:\nFor The Horde!\nCategory:\nPlayer vs. Player" }
entries[44225] = { ["name"] = "Reins of the Armored Brown Bear", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nRequires any Alliance race\nUse: Teaches you how to summon this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"This ursine mount's swiftness is enhanced by its heavy armor, imbued with magic from Kirin Tor magi.\"\nVendor:\nMei Francis\nZone:\nCrystalsong Forest\nCost:" }
entries[44226] = { ["name"] = "Reins of the Armored Brown Bear", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nRequires any Horde race\nUse: Teaches you how to summon this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Your cries of \"For the Horde!\" will be much more menacing from atop a heavily armored bear that's barreling down on Alliance at top speed.\"\nVendor:\nMei Francis\nZone:\nCrystalsong Forest\nCost:" }
entries[44228] = { ["name"] = "Baby Spice", ["text"] = "Binds when picked up\nUse: Reduces the target's size by 50% turning them into a baby. (10 Sec Cooldown)\nSell Price:" }
entries[44229] = { ["name"] = "Loaned Wind Rider Reins", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Summons and dismisses a rideable Loaned Wind Rider mount. This mount can only be summoned in the Storm Peaks, Icecrown and Sholazar Basin. (3 Sec Cooldown)\nRequires level 1 to 80 ( 80)" }
entries[44230] = { ["name"] = "Reins of the Wooly Mammoth", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nRequires any Alliance race\nUse: Teaches you how to summon this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Directly descended from the original progenitor of the mammoth race, wooly mammoths are considered more feral and primal than their shorter-haired cousins.\"\nVendor:\nMei Francis\nZone:\nCrystalsong Forest\nCost:" }
entries[44231] = { ["name"] = "Reins of the Wooly Mammoth", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nRequires any Horde race\nUse: Teaches you how to summon this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"This wild variant of the mammoth is not bred for riding. Most wooly mammoths are captured in the wild and tamed by their riders, resulting in a fierce, cunning mount.\"\nVendor:\nMei Francis\nZone:\nCrystalsong Forest\nCost:" }
entries[44234] = { ["name"] = "Reins of the Traveler's Tundra Mammoth", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nRequires any Horde race\nUse: Teaches you how to summon this three-person mount with vendors.\nCalls forth the Traveler's Tundra Mammoth, complete with two buddies!\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Riders and merchants alike trust only this strong and steadfast mammoth to carry them safely across the frigid tundra.\"\nVendor:\nMei Francis\nZone:\nCrystalsong Forest\nCost:" }
entries[44235] = { ["name"] = "Reins of the Traveler's Tundra Mammoth", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nRequires any Alliance race\nUse: Teaches you how to summon this three-person mount with vendors.\nCalls forth the Traveler's Tundra Mammoth, complete with two buddies!\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Ancient manuscripts depict merchants traveling across the frozen tundra with these colossal beasts, leading scholars to believe they are the first domesticated mounts.\"\nVendor:\nMei Francis\nZone:\nCrystalsong Forest\nCost:" }
