entries[44502] = { ["name"] = "Schematic: Mechano-Hog", ["text"] = "Binds when picked up\nUse: Teaches you how to make a Mechano-Hog.\nRequires Northrend Engineering (75)\nRequires Horde Expedition\n- Exalted\nSell Price:\nHorde\nMechano-Hog\nMount\n(Account-wide)\nRequires any Horde race\nUse: Teaches you how to ride this sweet hog.\nRides and parks a badass Mechano-Hog.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"Difficult to build and to maintain, these hogs more than make up for their expense through sheer cool factor.\"\nProfession:\nEngineering\nAlliance\nMekgineer's Chopper\nMount\n(Account-wide)\nRequires any Alliance race\nUse: Teaches you how to ride this chopper.\nRides and parks a rockin' Mekgineer's Chopper.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Sporting superb engineering craftsmanship, this chopper is one of the few personal vehicles on Azeroth built for two.\"\nProfession:\nEngineeringRequires Titansteel Bar (12), Handful of Cobalt Bolts (40), Arctic Fur (2), Salvaged Iron Golem Parts , Goblin-Machined Piston (8), Elementium-Plated Exhaust Pipe" }
entries[44503] = { ["name"] = "Schematic: Mekgineer's Chopper", ["text"] = "Binds when picked up\nUse: Teaches you how to make a Mekgineer's Chopper.\nRequires Northrend Engineering (75)\nRequires Alliance Vanguard\n- Exalted\nSell Price:\nAlliance\nMekgineer's Chopper\nMount\n(Account-wide)\nRequires any Alliance race\nUse: Teaches you how to ride this chopper.\nRides and parks a rockin' Mekgineer's Chopper.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Sporting superb engineering craftsmanship, this chopper is one of the few personal vehicles on Azeroth built for two.\"\nProfession:\nEngineering\nHorde\nMechano-Hog\nMount\n(Account-wide)\nRequires any Horde race\nUse: Teaches you how to ride this sweet hog.\nRides and parks a badass Mechano-Hog.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"Difficult to build and to maintain, these hogs more than make up for their expense through sheer cool factor.\"\nProfession:\nEngineeringRequires Titansteel Bar (12), Handful of Cobalt Bolts (40), Arctic Fur (2), Salvaged Iron Golem Parts , Goblin-Machined Piston (8), Elementium-Plated Exhaust Pipe" }
